1	import type { NoteEntry, VisibleNavigationItem } from "@typenotes/shared/types";
2	import type { NotePreview } from "@typenotes/shared/format";
3	
4	// Feed is not the folder tree. It is a synthetic hierarchy built from note
5	// timestamps so the navigation UI can browse recent work by time bucket.
6	export type FeedTreeNodeKind =
7	  | "special"
8	  | "year"
9	  | "quarter"
10	  | "month"
11	  | "week"
12	  | "day"
13	  | "undated";
14	
15	export type FeedTreeNode = {
16	  id: string;
17	  name: string;
18	  kind: FeedTreeNodeKind;
19	  parentId: string | null;
20	  rangeStartMs: number | null;
21	  rangeEndMs: number | null;
22	  children: FeedTreeNode[];
23	  notes: Array<NoteEntry & { timestampMs: number }>;
24	  noteCount: number;
25	  latestMs: number;
26	  rank: number;
27	};
28	
29	export type FeedTreeBuildResult = {
30	  treeData: FeedTreeNode[];
31	  nodeById: Map<string, FeedTreeNode>;
32	};
33	
34	type FeedNodeBuilder = {
35	  id: string;
36	  name: string;
37	  kind: FeedTreeNodeKind;
38	  parentId: string | null;
39	  rangeStartMs: number | null;
40	  rangeEndMs: number | null;
41	  children: Map<string, FeedNodeBuilder>;
42	  notes: Array<NoteEntry & { timestampMs: number }>;
43	  latestMs: number;
44	  rank: number;
45	  calendarEnsured?: boolean;
46	};
47	
48	// Intl is the hot path of this module: building the feed for thousands of
49	// notes used to spend seconds inside toLocaleDateString/localeCompare. Labels
50	// are deterministic per weekday/month/week, so they are cached, and one shared
51	// Collator replaces per-call localeCompare in the sorts.
52	const nameCollator = new Intl.Collator();
53	const compareNames = (left: string, right: string) => nameCollator.compare(left, right);
54	
55	const DAY_MS = 86_400_000;
56	
57	const SPECIAL_GROUP_ORDER: Record<string, number> = {
58	  today: 0,
59	  yesterday: 1,
60	  "last-week": 2,
61	  undated: 99_999,
62	};
63	
64	const getWeekdayOrder = (date: Date) => (date.getDay() + 6) % 7;
65	
66	const createBuilder = (
67	  id: string,
68	  name: string,
69	  kind: FeedTreeNodeKind,
70	  parentId: string | null,
71	  rank: number,
72	  rangeStartMs: number | null = null,
73	  rangeEndMs: number | null = null
74	): FeedNodeBuilder => ({
75	  id,
76	  name,
77	  kind,
78	  parentId,
79	  rangeStartMs,
80	  rangeEndMs,
81	  children: new Map(),
82	  notes: [],
83	  latestMs: 0,
84	  rank,
85	});
86	
87	const ensureBuilder = (
88	  parent: FeedNodeBuilder,
89	  id: string,
90	  name: string,
91	  kind: FeedTreeNodeKind,
92	  rank: number,
93	  rangeStartMs: number | null = null,
94	  rangeEndMs: number | null = null
95	) => {
96	  const existing = parent.children.get(id);
97	  if (existing) {
98	    return existing;
99	  }
100	  const next = createBuilder(
101	    id,
102	    name,
103	    kind,
104	    parent.id,
105	    rank,
106	    rangeStartMs,
107	    rangeEndMs
108	  );
109	  parent.children.set(id, next);
110	  return next;
111	};
112	
113	const getStartOfDayMs = (date: Date) => {
114	  const value = new Date(date.getFullYear(), date.getMonth(), date.getDate());
115	  return value.getTime();
116	};
117	
118	const getEndOfDayMs = (date: Date) =>
119	  new Date(
120	    date.getFullYear(),
121	    date.getMonth(),
122	    date.getDate(),
123	    23,
124	    59,
125	    59,
126	    999
127	  ).getTime();
128	
129	type FeedDateRange = {
130	  rangeStartMs: number;
131	  rangeEndMs: number;
132	};
133	
134	const clampRangeEnd = (rangeEndMs: number, now: Date) =>
135	  Math.min(rangeEndMs, now.getTime());
136	
137	const getDayRange = (date: Date, now: Date): FeedDateRange => ({
138	  rangeStartMs: getStartOfDayMs(date),
139	  rangeEndMs: clampRangeEnd(getEndOfDayMs(date), now),
140	});
141	
142	const getMonthRange = (date: Date, now: Date): FeedDateRange => ({
143	  rangeStartMs: new Date(date.getFullYear(), date.getMonth(), 1).getTime(),
144	  rangeEndMs: clampRangeEnd(
145	    new Date(
146	      date.getFullYear(),
147	      date.getMonth() + 1,
148	      0,
149	      23,
150	      59,
151	      59,
152	      999
153	    ).getTime(),
154	    now
155	  ),
156	});
157	
158	const getYearRange = (date: Date, now: Date): FeedDateRange => ({
159	  rangeStartMs: new Date(date.getFullYear(), 0, 1).getTime(),
160	  rangeEndMs: clampRangeEnd(
161	    new Date(date.getFullYear(), 11, 31, 23, 59, 59, 999).getTime(),
162	    now
163	  ),
164	});
165	
166	const getFirstMondayDay = (date: Date) =>
167	  1 + ((8 - new Date(date.getFullYear(), date.getMonth(), 1).getDay()) % 7);
168	
169	const getWeekOfMonth = (date: Date) => {
170	  const firstMonday = getFirstMondayDay(date);
171	  if (date.getDate() < firstMonday) {
172	    return 0;
173	  }
174	  return Math.floor((date.getDate() - firstMonday) / 7) + 1;
175	};
176	
177	const getWeekDateBounds = (date: Date, week = getWeekOfMonth(date)) => {
178	  const firstMonday = getFirstMondayDay(date);
179	  const startDay = week === 0 ? 1 : firstMonday + (week - 1) * 7;
180	  const endDay = Math.min(
181	    week === 0 ? firstMonday - 1 : startDay + 6,
182	    new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate()
183	  );
184	  return {
185	    week,
186	    start: new Date(date.getFullYear(), date.getMonth(), startDay),
187	    end: new Date(
188	      date.getFullYear(),
189	      date.getMonth(),
190	      endDay,
191	      23,
192	      59,
193	      59,
194	      999
195	    ),
196	  };
197	};
198	
199	const getWeekRange = (date: Date, now: Date): FeedDateRange => {
200	  const { start, end } = getWeekDateBounds(date);
201	  return {
202	    rangeStartMs: start.getTime(),
203	    rangeEndMs: clampRangeEnd(end.getTime(), now),
204	  };
205	};
206	
207	const weekRangeLabelCache = new Map<string, string>();
208	
209	const getWeekRangeLabel = (date: Date, week = getWeekOfMonth(date)) => {
210	  const cacheKey = `${date.getFullYear()}:${date.getMonth()}:${week}`;
211	  const cached = weekRangeLabelCache.get(cacheKey);
212	  if (cached) {
213	    return cached;
214	  }
215	  const { start, end } = getWeekDateBounds(date, week);
216	  const formatDate = (value: Date) =>
217	    value.toLocaleDateString([], {
218	      month: "long",
219	      day: "numeric",
220	    });
221	  const prefix = week === 0 ? "Month start" : `Week ${week}`;
222	  const label = `${prefix} (${formatDate(start)} - ${formatDate(end)})`;
223	  weekRangeLabelCache.set(cacheKey, label);
224	  return label;
225	};
226	
227	const getQuarter = (date: Date) => Math.floor(date.getMonth() / 3) + 1;
228	
229	const getQuarterRange = (date: Date, now: Date): FeedDateRange => {
230	  const firstMonth = (getQuarter(date) - 1) * 3;
231	  return {
232	    rangeStartMs: new Date(date.getFullYear(), firstMonth, 1).getTime(),
233	    rangeEndMs: clampRangeEnd(
234	      new Date(
235	        date.getFullYear(),
236	        firstMonth + 3,
237	        0,
238	        23,
239	        59,
240	        59,
241	        999
242	      ).getTime(),
243	      now
244	    ),
245	  };
246	};
247	
248	const getQuarterSortRank = (quarter: number) => 4 - quarter;
249	
250	const getMonthSortRank = (date: Date) => 12 - (date.getMonth() + 1);
251	
252	const getYearSortRank = (year: number) => 10_000 - year;
253	
254	const titleCase = (value: string) =>
255	  value.length > 0 ? value[0].toUpperCase() + value.slice(1) : value;
256	
257	const monthLabelCache = new Map<number, string>();
258	
259	const getMonthLabel = (date: Date) => {
260	  const cacheKey = date.getMonth();
261	  const cached = monthLabelCache.get(cacheKey);
262	  if (cached) {
263	    return cached;
264	  }
265	  const label = date.toLocaleDateString([], {
266	    month: "long",
267	  });
268	  monthLabelCache.set(cacheKey, label);
269	  return label;
270	};
271	
272	const weekdayLabelCache = new Map<number, string>();
273	
274	const getWeekdayLabel = (date: Date) => {
275	  const cacheKey = date.getDay();
276	  const cached = weekdayLabelCache.get(cacheKey);
277	  if (cached) {
278	    return cached;
279	  }
280	  const label = titleCase(
281	    date.toLocaleDateString([], {
282	      weekday: "long",
283	    })
284	  );
285	  weekdayLabelCache.set(cacheKey, label);
286	  return label;
287	};
288	
289	const getSpecialLabel = (kind: "today" | "yesterday" | "last-week" | "undated") => {
290	  if (kind === "today") return "Today";
291	  if (kind === "yesterday") return "Yesterday";
292	  if (kind === "last-week") return "Last week";
293	  return "Undated";
294	};
295	
296	const buildPathSegments = (segments: Array<string | number>) =>
297	  `feed:${segments.map((segment) => String(segment)).join(":")}`;
298	
299	const getUndatedNode = (root: FeedNodeBuilder) =>
300	  ensureBuilder(
301	    root,
302	    buildPathSegments(["undated"]),
303	    getSpecialLabel("undated"),
304	    "undated",
305	    SPECIAL_GROUP_ORDER.undated
306	  );
307	
308	const addNoteToBuilder = (builder: FeedNodeBuilder, note: NoteEntry, timestampMs: number) => {
309	  builder.notes.push({ ...note, timestampMs });
310	  if (timestampMs > builder.latestMs) {
311	    builder.latestMs = timestampMs;
312	  }
313	};
314	
315	const addNoteToMonth = (
316	  month: FeedNodeBuilder,
317	  monthPathSegments: Array<string | number>,
318	  note: NoteEntry,
319	  timestampMs: number,
320	  date: Date,
321	  now: Date
322	) => {
323	  const week = getWeekOfMonth(date);
324	  const weekPathSegments = [...monthPathSegments, "week", week];
325	  const weekRange = getWeekRange(date, now);
326	  const weekNode = ensureBuilder(
327	    month,
328	    buildPathSegments(weekPathSegments),
329	    getWeekRangeLabel(date),
330	    "week",
331	    week,
332	    weekRange.rangeStartMs,
333	    weekRange.rangeEndMs
334	  );
335	  const dayRange = getDayRange(date, now);
336	  const dayNode = ensureBuilder(
337	    weekNode,
338	    buildPathSegments([...weekPathSegments, "day", date.getDate()]),
339	    getWeekdayLabel(date),
340	    "day",
341	    date.getDate(),
342	    dayRange.rangeStartMs,
343	    dayRange.rangeEndMs
344	  );
345	  addNoteToBuilder(dayNode, note, timestampMs);
346	};
347	
348	const ensureMonthCalendar = (
349	  month: FeedNodeBuilder,
350	  monthPathSegments: Array<string | number>,
351	  date: Date,
352	  now: Date
353	) => {
354	  // The calendar skeleton depends only on (year, month, now) — build it once
355	  // per month builder instead of once per note.
356	  if (month.calendarEnsured) {
357	    return;
358	  }
359	  month.calendarEnsured = true;
360	  const monthEndDay = new Date(
361	    date.getFullYear(),
362	    date.getMonth() + 1,
363	    0
364	  ).getDate();
365	  const visibleEndDay =
366	    date.getFullYear() === now.getFullYear() &&
367	    date.getMonth() === now.getMonth()
368	      ? Math.min(monthEndDay, now.getDate())
369	      : monthEndDay;
370	  const firstMonday = getFirstMondayDay(date);
371	  const firstWeek = firstMonday > 1 ? 0 : 1;
372	  const lastWeek = getWeekOfMonth(
373	    new Date(date.getFullYear(), date.getMonth(), visibleEndDay)
374	  );
375	
376	  for (let week = firstWeek; week <= lastWeek; week += 1) {
377	    const bounds = getWeekDateBounds(date, week);
378	    if (bounds.start.getDate() > visibleEndDay) {
379	      break;
380	    }
381	    const endDay = Math.min(bounds.end.getDate(), visibleEndDay);
382	    const rangeDate = new Date(
383	      date.getFullYear(),
384	      date.getMonth(),
385	      bounds.start.getDate()
386	    );
387	    const weekPathSegments = [...monthPathSegments, "week", week];
388	    const weekRange = getWeekRange(rangeDate, now);
389	    const weekNode = ensureBuilder(
390	      month,
391	      buildPathSegments(weekPathSegments),
392	      getWeekRangeLabel(date, week),
393	      "week",
394	      week,
395	      weekRange.rangeStartMs,
396	      Math.min(
397	        weekRange.rangeEndMs,
398	        getEndOfDayMs(
399	          new Date(date.getFullYear(), date.getMonth(), endDay)
400	        )
401	      )
402	    );
403	
404	    for (
405	      let day = bounds.start.getDate();
406	      day <= endDay;
407	      day += 1
408	    ) {
409	      const dayDate = new Date(date.getFullYear(), date.getMonth(), day);
410	      const dayRange = getDayRange(dayDate, now);
411	      ensureBuilder(
412	        weekNode,
413	        buildPathSegments([...weekPathSegments, "day", day]),
414	        getWeekdayLabel(dayDate),
415	        "day",
416	        day,
417	        dayRange.rangeStartMs,
418	        dayRange.rangeEndMs
419	      );
420	    }
421	  }
422	};
423	
424	const finalizeBuilder = (builder: FeedNodeBuilder): FeedTreeNode => {
425	  const children = [...builder.children.values()]
426	    .map((child) => finalizeBuilder(child))
427	    .sort((left, right) => {
428	      if (left.rank !== right.rank) {
429	        return left.rank - right.rank;
430	      }
431	      if (left.latestMs !== right.latestMs) {
432	        return right.latestMs - left.latestMs;
433	      }
434	      return compareNames(left.name, right.name);
435	    });
436	  const noteCount = builder.notes.length + children.reduce((total, child) => total + child.noteCount, 0);
437	  return {
438	    id: builder.id,
439	    name: builder.name,
440	    kind: builder.kind,
441	    parentId: builder.parentId,
442	    rangeStartMs: builder.rangeStartMs,
443	    rangeEndMs: builder.rangeEndMs,
444	    children,
445	    notes: [...builder.notes].sort((left, right) => {
446	      if (left.timestampMs !== right.timestampMs) {
447	        return right.timestampMs - left.timestampMs;
448	      }
449	      return compareNames(left.name, right.name);
450	    }),
451	    noteCount,
452	    latestMs: builder.latestMs,
453	    rank: builder.rank,
454	  };
455	};
456	
457	const getFeedTimestamp = (preview?: NotePreview) =>
458	  preview?.createdMs ?? preview?.updatedMs ?? null;
459	
460	const addRecentNote = (
461	  root: FeedNodeBuilder,
462	  note: NoteEntry,
463	  timestampMs: number,
464	  now: Date
465	) => {
466	  const date = new Date(timestampMs);
467	  const ageDays = Math.floor(
468	    (getStartOfDayMs(now) - getStartOfDayMs(date)) / DAY_MS
469	  );
470	  if (ageDays <= 0) {
471	    const todayRange = getDayRange(now, now);
472	    const today = ensureBuilder(
473	      root,
474	      buildPathSegments(["today"]),
475	      getSpecialLabel("today"),
476	      "special",
477	      SPECIAL_GROUP_ORDER.today,
478	      todayRange.rangeStartMs,
479	      todayRange.rangeEndMs
480	    );
481	    addNoteToBuilder(today, note, timestampMs);
482	    return;
483	  }
484	
485	  if (ageDays === 1) {
486	    const yesterdayRange = getDayRange(date, now);
487	    const yesterday = ensureBuilder(
488	      root,
489	      buildPathSegments(["yesterday"]),
490	      getSpecialLabel("yesterday"),
491	      "special",
492	      SPECIAL_GROUP_ORDER.yesterday,
493	      yesterdayRange.rangeStartMs,
494	      yesterdayRange.rangeEndMs
495	    );
496	    addNoteToBuilder(yesterday, note, timestampMs);
497	    return;
498	  }
499	
500	  if (ageDays < 7) {
501	    const lastWeekStart = new Date(
502	      now.getFullYear(),
503	      now.getMonth(),
504	      now.getDate() - 6
505	    );
506	    const lastWeekEnd = new Date(
507	      now.getFullYear(),
508	      now.getMonth(),
509	      now.getDate() - 2,
510	      23,
511	      59,
512	      59,
513	      999
514	    );
515	    const lastWeek = ensureBuilder(
516	      root,
517	      buildPathSegments(["last-week"]),
518	      getSpecialLabel("last-week"),
519	      "special",
520	      SPECIAL_GROUP_ORDER["last-week"],
521	      lastWeekStart.getTime(),
522	      lastWeekEnd.getTime()
523	    );
524	    const dayId = buildPathSegments(["last-week", "day", date.getDay()]);
525	    const dayRange = getDayRange(date, now);
526	    const day = ensureBuilder(
527	      lastWeek,
528	      dayId,
529	      getWeekdayLabel(date),
530	      "day",
531	      getWeekdayOrder(date),
532	      dayRange.rangeStartMs,
533	      dayRange.rangeEndMs
534	    );
535	    addNoteToBuilder(day, note, timestampMs);
536	    return;
537	  }
538	
539	  if (date.getFullYear() === now.getFullYear()) {
540	    const monthPathSegments = [
541	      "month",
542	      date.getFullYear(),
543	      date.getMonth() + 1,
544	    ];
545	    const monthId = buildPathSegments(monthPathSegments);
546	    const monthRange = getMonthRange(date, now);
547	    const month = ensureBuilder(
548	      root,
549	      monthId,
550	      getMonthLabel(date),
551	      "month",
552	      10 + getMonthSortRank(date),
553	      monthRange.rangeStartMs,
554	      monthRange.rangeEndMs
555	    );
556	    ensureMonthCalendar(month, monthPathSegments, date, now);
557	    addNoteToMonth(month, monthPathSegments, note, timestampMs, date, now);
558	    return;
559	  }
560	
561	  const yearId = buildPathSegments(["year", date.getFullYear()]);
562	  const yearRange = getYearRange(date, now);
563	  const year = ensureBuilder(
564	    root,
565	    yearId,
566	    String(date.getFullYear()),
567	    "year",
568	    getYearSortRank(date.getFullYear()),
569	    yearRange.rangeStartMs,
570	    yearRange.rangeEndMs
571	  );
572	  const quarter = getQuarter(date);
573	  const quarterId = buildPathSegments(["year", date.getFullYear(), "quarter", quarter]);
574	  const quarterRange = getQuarterRange(date, now);
575	  const quarterNode = ensureBuilder(
576	    year,
577	    quarterId,
578	    `Q${quarter}`,
579	    "quarter",
580	    getQuarterSortRank(quarter),
581	    quarterRange.rangeStartMs,
582	    quarterRange.rangeEndMs
583	  );
584	  const monthPathSegments = [
585	    "year",
586	    date.getFullYear(),
587	    "quarter",
588	    quarter,
589	    "month",
590	    date.getMonth() + 1,
591	  ];
592	  const monthId = buildPathSegments(monthPathSegments);
593	  const monthRange = getMonthRange(date, now);
594	  const monthNode = ensureBuilder(
595	    quarterNode,
596	    monthId,
597	    getMonthLabel(date),
598	    "month",
599	    10 + getMonthSortRank(date),
600	    monthRange.rangeStartMs,
601	    monthRange.rangeEndMs
602	  );
603	  ensureMonthCalendar(monthNode, monthPathSegments, date, now);
604	  addNoteToMonth(monthNode, monthPathSegments, note, timestampMs, date, now);
605	};
606	
607	export function buildFeedTree(
608	  notes: NoteEntry[],
609	  previews: Record<string, NotePreview>,
610	  hideArchivedNotes: boolean
611	): FeedTreeBuildResult {
612	  const now = new Date();
613	  const root = createBuilder("feed:root", "Feed", "special", null, 0);
614	
615	  notes.forEach((note) => {
616	    const preview = previews[note.path];
617	    if (!preview) {
618	      return;
619	    }
620	    if (hideArchivedNotes && preview.isArchived) {
621	      return;
622	    }
623	    const timestampMs = getFeedTimestamp(preview);
624	    if (timestampMs == null) {
625	      const undated = getUndatedNode(root);
626	      addNoteToBuilder(undated, note, 0);
627	      return;
628	    }
629	    const date = new Date(timestampMs);
630	    if (Number.isNaN(date.getTime())) {
631	      addNoteToBuilder(getUndatedNode(root), note, 0);
632	      return;
633	    }
634	    addRecentNote(root, note, timestampMs, now);
635	  });
636	
637	  const treeData = [...root.children.values()]
638	    .map((child) => finalizeBuilder(child))
639	    .sort((left, right) => {
640	      if (left.rank !== right.rank) {
641	        return left.rank - right.rank;
642	      }
643	      if (left.latestMs !== right.latestMs) {
644	        return right.latestMs - left.latestMs;
645	      }
646	      return compareNames(left.name, right.name);
647	    });
648	
649	  const nodeById = new Map<string, FeedTreeNode>();
650	  const walk = (node: FeedTreeNode) => {
651	    nodeById.set(node.id, node);
652	    node.children.forEach(walk);
653	  };
654	  treeData.forEach(walk);
655	  return { treeData, nodeById };
656	}
657	
658	export function buildVisibleFeedNavigationItems(
659	  treeData: FeedTreeNode[],
660	  expanded: Set<string>,
661	  shouldNestNotesInNavigation: boolean
662	): VisibleNavigationItem[] {
663	  const items: VisibleNavigationItem[] = [];
664	
665	  const walk = (nodes: FeedTreeNode[], parentId: string | null) => {
666	    nodes.forEach((node) => {
667	      items.push({
668	        type: "folder",
669	        id: node.id,
670	        parentId,
671	      });
672	
673	      const noteRows = shouldNestNotesInNavigation ? node.notes : [];
674	      const hasNestedItems = node.children.length > 0 || noteRows.length > 0;
675	      if (!hasNestedItems || !expanded.has(node.id)) {
676	        return;
677	      }
678	
679	      noteRows.forEach((note) => {
680	        items.push({
681	          type: "note",
682	          id: note.path,
683	          parentId: node.id,
684	        });
685	      });
686	
687	      walk(node.children, node.id);
688	    });
689	  };
690	
691	  walk(treeData, null);
692	  return items;
693	}
694	
695	export function collectFeedNotes(
696	  node: FeedTreeNode | null
697	): Array<NoteEntry & { timestampMs: number }> {
698	  if (!node) {
699	    return [];
700	  }
701	  const notes = [...node.notes]
702	    .sort((left, right) => {
703	      if (left.timestampMs !== right.timestampMs) {
704	        return right.timestampMs - left.timestampMs;
705	      }
706	      return compareNames(left.name, right.name);
707	    });
708	  node.children.forEach((child) => {
709	    notes.push(...collectFeedNotes(child));
710	  });
711	  return notes.sort((left, right) => {
712	    if (left.timestampMs !== right.timestampMs) {
713	      return right.timestampMs - left.timestampMs;
714	    }
715	    return compareNames(left.name, right.name);
716	  });
717	}
718	
719	export function getFirstFeedGroupId(treeData: FeedTreeNode[]): string {
720	  return treeData[0]?.id ?? "";
721	}
722	
723	export function findFeedNode(
724	  treeData: FeedTreeNode[],
725	  targetId: string
726	): FeedTreeNode | null {
727	  for (const node of treeData) {
728	    if (node.id === targetId) {
729	      return node;
730	    }
731	    const match = findFeedNode(node.children, targetId);
732	    if (match) {
733	      return match;
734	    }
735	  }
736	  return null;
737	}
738	
739	export function getLatestFeedTargetTimestamp(
740	  node: FeedTreeNode | null,
741	  now: Date = new Date()
742	): number | null {
743	  if (node?.rangeStartMs == null || node.rangeEndMs == null) {
744	    return null;
745	  }
746	  const latestMs = Math.min(node.rangeEndMs, now.getTime());
747	  return latestMs >= node.rangeStartMs ? latestMs : null;
748	}
