1	import { useCallback, useRef, useState } from "react";
2	import type {
3	  DragEndEvent,
4	  DragMoveEvent,
5	  DragOverEvent,
6	  DragStartEvent,
7	} from "@dnd-kit/core";
8	import { moveItems, setOrder } from "@/features/notes/api/notes-api";
9	import { logGroup } from "@/shared/api/invoke";
10	import type { DragData, FolderNode } from "@typenotes/shared/types";
11	import { isSystemFolder } from "@typenotes/shared/constants";
12	import { getNoteParentPath } from "@typenotes/shared/notes";
13	import { DROP_PREFIX } from "../model/tree-dnd";
14	import {
15	  findNode,
16	  findParentAndIndex,
17	  getNodeById,
18	  removeNodes,
19	  insertNodes,
20	  parseDropTargetId,
21	  sortIdsByTreeOrder,
22	  isInDraggedSubtree,
23	  getTopLevelSelected,
24	  arraysEqual,
25	  buildFolderOrderMap,
26	  applyFolderOrder,
27	  buildNoteOrderMap,
28	  reorderList,
29	  flattenTree,
30	} from "../model/tree-ops";
31	import type { TreeItem } from "../model/types";
32	import type { FlattenedItem } from "../model/types";
33	
34	type UseDragDropArgs = {
35	  tree: FolderNode | null;
36	  setTree: React.Dispatch<React.SetStateAction<FolderNode | null>>;
37	  treeData: TreeItem[];
38	  flatItems: FlattenedItem[];
39	  orderedIds: string[];
40	  expanded: Set<string>;
41	  setExpanded: React.Dispatch<React.SetStateAction<Set<string>>>;
42	  selectedFolders: Set<string>;
43	  setSelectedFolders: React.Dispatch<React.SetStateAction<Set<string>>>;
44	  setLastSelectedFolder: (path: string) => void;
45	  selectedNotes: Set<string>;
46	  setSelectedNotes: React.Dispatch<React.SetStateAction<Set<string>>>;
47	  setLastSelectedNote: (path: string) => void;
48	  setActiveNote: (path: string | null) => void;
49	  activeNote: string | null;
50	  clearNote: () => void;
51	  refreshTree: () => Promise<void>;
52	  parentById: Record<string, string | null>;
53	};
54	
55	export function useDragDrop({
56	  tree,
57	  setTree,
58	  treeData,
59	  flatItems,
60	  orderedIds,
61	  expanded,
62	  setExpanded,
63	  selectedFolders,
64	  setSelectedFolders,
65	  setLastSelectedFolder,
66	  selectedNotes,
67	  setSelectedNotes,
68	  setLastSelectedNote,
69	  setActiveNote,
70	  activeNote,
71	  clearNote,
72	  refreshTree,
73	  parentById,
74	}: UseDragDropArgs) {
75	  const [activeId, setActiveId] = useState<string | null>(null);
76	  const [edgeSnap, setEdgeSnap] = useState<{
77	    id: string;
78	    position: "before" | "after";
79	  } | null>(null);
80	  const activeDrag = useRef<DragData | null>(null);
81	  const dragStartPoint = useRef<{ x: number; y: number } | null>(null);
82	  const expandTimeoutRef = useRef<number | null>(null);
83	  const expandTargetRef = useRef<string | null>(null);
84	
85	  const handleDragStart = useCallback(
86	    ({ active, activatorEvent }: DragStartEvent) => {
87	      const data = active.data.current as DragData | undefined;
88	      if (!data) return;
89	      activeDrag.current = data;
90	      logGroup("drag start", {
91	        type: data.type,
92	        path: "path" in data ? data.path : undefined,
93	        id: active.id.toString(),
94	      });
95	      if (data.type === "folder") {
96	        const point =
97	          activatorEvent instanceof globalThis.MouseEvent
98	            ? { x: activatorEvent.clientX, y: activatorEvent.clientY }
99	            : null;
100	        dragStartPoint.current = point;
101	        setActiveId(active.id.toString());
102	        setSelectedFolders((prev) =>
103	          prev.has(data.path) ? prev : new Set([data.path])
104	        );
105	        setLastSelectedFolder(data.path);
106	        document.body.style.setProperty("cursor", "grabbing");
107	      }
108	      if (data.type === "note") {
109	        setSelectedNotes((prev) =>
110	          prev.has(data.path) ? prev : new Set([data.path])
111	        );
112	        setLastSelectedNote(data.path);
113	        setActiveNote(data.path);
114	      }
115	    },
116	    [setSelectedFolders, setLastSelectedFolder, setSelectedNotes, setLastSelectedNote, setActiveNote]
117	  );
118	
119	  const handleDragMove = useCallback(
120	    (event: DragMoveEvent) => {
121	      if (activeDrag.current?.type !== "folder") return;
122	      const { active, over } = event;
123	      if (!active || !over) {
124	        setEdgeSnap(null);
125	        if (expandTimeoutRef.current) {
126	          window.clearTimeout(expandTimeoutRef.current);
127	          expandTimeoutRef.current = null;
128	        }
129	        expandTargetRef.current = null;
130	        return;
131	      }
132	      const dropTarget = parseDropTargetId(over.id);
133	      if (!dropTarget || dropTarget.type !== "item" || dropTarget.position !== "inside") {
134	        setEdgeSnap(null);
135	        if (expandTimeoutRef.current) {
136	          window.clearTimeout(expandTimeoutRef.current);
137	          expandTimeoutRef.current = null;
138	        }
139	        expandTargetRef.current = null;
140	        return;
141	      }
142	
143	      // Spring-load: hovering a collapsed folder for 500ms auto-expands it, so
144	      // you can drill into a nested folder mid-drag without dropping first.
145	      const overNode = getNodeById(treeData, dropTarget.itemId);
146	      const hasChildren = Boolean(overNode?.children && overNode.children.length > 0);
147	      const isCollapsed = hasChildren && !expanded.has(dropTarget.itemId);
148	      if (isCollapsed) {
149	        if (expandTargetRef.current !== dropTarget.itemId) {
150	          if (expandTimeoutRef.current) window.clearTimeout(expandTimeoutRef.current);
151	          expandTargetRef.current = dropTarget.itemId;
152	          expandTimeoutRef.current = window.setTimeout(() => {
153	            setExpanded((prev) => {
154	              const next = new Set(prev);
155	              next.add(dropTarget.itemId);
156	              return next;
157	            });
158	          }, 500);
159	        }
160	      } else if (expandTargetRef.current) {
161	        if (expandTimeoutRef.current) {
162	          window.clearTimeout(expandTimeoutRef.current);
163	          expandTimeoutRef.current = null;
164	        }
165	        expandTargetRef.current = null;
166	      }
167	
168	      const overRect = over.rect;
169	      if (!overRect) {
170	        setEdgeSnap(null);
171	        return;
172	      }
173	
174	      // Prefer the live pointer position (drag-start point + dnd-kit delta);
175	      // fall back to the dragged row's center when the drag wasn't mouse-driven.
176	      let pointerY: number | null = null;
177	      if (dragStartPoint.current && typeof event.delta?.y === "number") {
178	        pointerY = dragStartPoint.current.y + event.delta.y;
179	      } else {
180	        const activeRect = active.rect.current?.translated ?? active.rect.current?.initial;
181	        if (activeRect) pointerY = activeRect.top + activeRect.height / 2;
182	      }
183	
184	      if (pointerY === null) {
185	        setEdgeSnap(null);
186	        return;
187	      }
188	
189	      // Top/bottom edge zones snap to before/after the row (reorder); the middle
190	      // means "drop inside". The zone is ~35% of row height, capped at 14px.
191	      const height = overRect.bottom - overRect.top;
192	      const threshold = Math.min(14, height * 0.35);
193	
194	      if (pointerY < overRect.top + threshold) {
195	        setEdgeSnap({ id: dropTarget.itemId, position: "before" });
196	        return;
197	      }
198	      if (pointerY > overRect.bottom - threshold) {
199	        if (hasChildren) {
200	          // "After" is ambiguous for a folder with children (after the row, or
201	          // after its whole subtree?), so fall back to dropping inside it.
202	          setEdgeSnap(null);
203	          return;
204	        }
205	        setEdgeSnap({ id: dropTarget.itemId, position: "after" });
206	        return;
207	      }
208	      setEdgeSnap(null);
209	    },
210	    [expanded, setExpanded, treeData]
211	  );
212	
213	  const handleDragOver = useCallback(
214	    (event: DragOverEvent) => {
215	      if (activeDrag.current?.type !== "folder") return;
216	      if (!event.over) setEdgeSnap(null);
217	    },
218	    []
219	  );
220	
221	  // Folder drops: reparent / reorder the dragged folder subtree, then persist
222	  // the moves + per-parent folder order and refresh if any parent changed.
223	  const handleFolderDragEnd = useCallback(
224	    async (event: DragEndEvent) => {
225	      const { over } = event;
226	
227	      setActiveId(null);
228	      setEdgeSnap(null);
229	      document.body.style.setProperty("cursor", "");
230	      dragStartPoint.current = null;
231	      activeDrag.current = null;
232	      if (expandTimeoutRef.current) {
233	        window.clearTimeout(expandTimeoutRef.current);
234	        expandTimeoutRef.current = null;
235	      }
236	      expandTargetRef.current = null;
237	
238	      if (!over) return;
239	
240	      const resolvedId =
241	        edgeSnap ? `${DROP_PREFIX}:${edgeSnap.id}:${edgeSnap.position}` : over.id;
242	      const dropTarget = parseDropTargetId(resolvedId);
243	      if (!dropTarget) {
244	        logGroup("drop ignored", { reason: "invalid target", overId: over.id });
245	        return;
246	      }
247	
248	      const selectedIdsList = Array.from(selectedFolders);
249	      const draggingIds = getTopLevelSelected(selectedIdsList, parentById);
250	      if (draggingIds.length === 0) {
251	        logGroup("drop ignored", { reason: "no dragging ids" });
252	        return;
253	      }
254	
255	      if (dropTarget.type === "item" && draggingIds.includes(dropTarget.itemId)) {
256	        logGroup("drop ignored", { reason: "target is dragged item", target: dropTarget });
257	        return;
258	      }
259	
260	      if (
261	        dropTarget.type === "item" &&
262	        isInDraggedSubtree(treeData, draggingIds, dropTarget.itemId)
263	      ) {
264	        logGroup("drop ignored", {
265	          reason: "target inside dragged subtree",
266	          target: dropTarget,
267	        });
268	        return;
269	      }
270	
271	      const orderedDraggingIds = sortIdsByTreeOrder(draggingIds, orderedIds);
272	      if (orderedDraggingIds.some(isSystemFolder)) {
273	        logGroup("drop ignored", { reason: "system folder drag blocked" });
274	        return;
275	      }
276	      // Optimistic local rebuild: pull the dragged subtrees out, then splice
277	      // them back in at the resolved target before persisting to the backend.
278	      const { tree: prunedTree, removed } = removeNodes(treeData, orderedDraggingIds);
279	      const removedMap = new Map(removed.map((node) => [node.id, node]));
280	      const nodesToInsert = orderedDraggingIds
281	        .map((id) => removedMap.get(id))
282	        .filter(Boolean) as TreeItem[];
283	
284	      if (nodesToInsert.length === 0) return;
285	
286	      let targetParentId: string | null = null;
287	      let targetIndex = 0;
288	
289	      if (dropTarget.type === "root") {
290	        targetParentId = null;
291	        targetIndex = prunedTree.length;
292	      } else if (dropTarget.position === "inside") {
293	        targetParentId = dropTarget.itemId;
294	        const parentNode = getNodeById(prunedTree, dropTarget.itemId);
295	        targetIndex = parentNode?.children?.length ?? 0;
296	      } else {
297	        const position = findParentAndIndex(prunedTree, dropTarget.itemId);
298	        if (!position) return;
299	        targetParentId = position.parentId;
300	        targetIndex = position.index + (dropTarget.position === "after" ? 1 : 0);
301	      }
302	
303	      const nextTree = insertNodes(prunedTree, targetParentId, targetIndex, nodesToInsert);
304	      logGroup("folder drag drop", {
305	        dropTarget,
306	        draggingIds: orderedDraggingIds,
307	        targetParentId: targetParentId ?? "",
308	        targetIndex,
309	        selectedFolders: Array.from(selectedFolders),
310	      });
311	
312	      const oldParentById: Record<string, string | null> = {};
313	      flatItems.forEach((item) => {
314	        oldParentById[item.id] = item.parentId;
315	      });
316	      const newParentById: Record<string, string | null> = {};
317	      flattenTree(nextTree).forEach((item) => {
318	        newParentById[item.id] = item.parentId;
319	      });
320	
321	      // Only folders whose parent actually changed need a filesystem move;
322	      // pure reordering within a parent is persisted via setOrder below.
323	      for (const id of orderedDraggingIds) {
324	        const oldParent = oldParentById[id] ?? null;
325	        const newParent = newParentById[id] ?? null;
326	        if (oldParent !== newParent) {
327	          await moveItems([id], newParent ?? "");
328	        }
329	      }
330	
331	      const noteOrderMap: Record<string, string[]> = {};
332	      buildNoteOrderMap(tree, noteOrderMap);
333	
334	      const currentOrderMap: Record<string, string[]> = {};
335	      const nextOrderMap: Record<string, string[]> = {};
336	      buildFolderOrderMap(treeData, null, currentOrderMap);
337	      buildFolderOrderMap(nextTree, null, nextOrderMap);
338	
339	      // Diff the per-parent child order so we only rewrite the .notes-order.json
340	      // of parents whose sequence actually changed, not every folder in the tree.
341	      const changedParents = Object.keys(nextOrderMap).filter(
342	        (parent) => !arraysEqual(nextOrderMap[parent], currentOrderMap[parent])
343	      );
344	
345	      logGroup("folder order delta", {
346	        changedParents,
347	        totalParents: Object.keys(nextOrderMap).length,
348	      });
349	
350	      for (const parentPath of changedParents) {
351	        await setOrder({
352	          parent: parentPath,
353	          folderOrder: nextOrderMap[parentPath],
354	          noteOrder: noteOrderMap[parentPath] || [],
355	        });
356	      }
357	
358	      if (changedParents.length > 0 && tree) {
359	        setTree(applyFolderOrder(tree, nextOrderMap));
360	      }
361	
362	      if (orderedDraggingIds.some((id) => oldParentById[id] !== newParentById[id])) {
363	        await refreshTree();
364	      }
365	    },
366	    [edgeSnap, flatItems, orderedIds, parentById, refreshTree, selectedFolders, setTree, tree, treeData]
367	  );
368	
369	  // Note drops: move the dragged note(s) to a folder / another note's parent,
370	  // or reorder within the current parent.
371	  const handleNoteDragEnd = useCallback(
372	    async (event: DragEndEvent) => {
373	      const { active, over } = event;
374	      const data = active.data.current as DragData | undefined;
375	      const overData = over?.data.current as DragData | undefined;
376	      if (!data || data.type !== "note") return;
377	
378	      activeDrag.current = null;
379	      if (!over || !overData) {
380	        logGroup("note drop ignored", { reason: "missing target" });
381	        return;
382	      }
383	      const selectedList = selectedNotes.has(data.path)
384	        ? Array.from(selectedNotes)
385	        : [data.path];
386	      const sourceParentPath = getNoteParentPath(data.path);
387	      if (overData.type === "folder") {
388	        logGroup("note move to folder", {
389	          notes: selectedList,
390	          destination: overData.path,
391	        });
392	        await moveItems(selectedList, overData.path);
393	        if (selectedList.includes(activeNote || "")) {
394	          setActiveNote(null);
395	          clearNote();
396	        }
397	        setSelectedNotes(new Set());
398	        setLastSelectedNote("");
399	        await refreshTree();
400	        return;
401	      }
402	      if (overData.type === "note") {
403	        const destinationParentPath = getNoteParentPath(overData.path);
404	        if (destinationParentPath !== sourceParentPath) {
405	          logGroup("note move to note parent", {
406	            notes: selectedList,
407	            destination: destinationParentPath,
408	            over: overData.path,
409	          });
410	          await moveItems(selectedList, destinationParentPath);
411	          if (selectedList.includes(activeNote || "")) {
412	            setActiveNote(null);
413	            clearNote();
414	          }
415	          setSelectedNotes(new Set());
416	          setLastSelectedNote("");
417	          await refreshTree();
418	          return;
419	        }
420	
421	        const parentNode = findNode(tree, destinationParentPath);
422	        if (!parentNode) {
423	          logGroup("note drop ignored", {
424	            reason: "missing destination parent",
425	            destinationParentPath,
426	          });
427	          return;
428	        }
429	
430	        const movingInParent = selectedList.filter(
431	          (notePath) => getNoteParentPath(notePath) === destinationParentPath
432	        );
433	        const movingNotes =
434	          movingInParent.length > 0 ? movingInParent : [data.path];
435	        if (movingNotes.includes(overData.path)) return;
436	
437	        const notePaths = parentNode.notes.map((n) => n.path);
438	        const newOrder = reorderList(notePaths, movingNotes, overData.path);
439	        const folderOrder = parentNode.children.map((c) => c.name);
440	        const noteOrder = newOrder.map((p) => p.split("/").pop() || p);
441	        logGroup("note reorder", {
442	          parent: parentNode.path,
443	          dragging: movingNotes,
444	          over: overData.path,
445	          noteOrder,
446	          folderOrder,
447	        });
448	        await setOrder({
449	          parent: parentNode.path,
450	          folderOrder,
451	          noteOrder,
452	        });
453	        await refreshTree();
454	      }
455	    },
456	    [
457	      activeNote,
458	      clearNote,
459	      refreshTree,
460	      selectedNotes,
461	      setActiveNote,
462	      setLastSelectedNote,
463	      setSelectedNotes,
464	      tree,
465	    ]
466	  );
467	
468	  const handleDragEnd = useCallback(
469	    async (event: DragEndEvent) => {
470	      const data = event.active.data.current as DragData | undefined;
471	      if (!data) return;
472	      if (data.type === "folder") {
473	        await handleFolderDragEnd(event);
474	        return;
475	      }
476	      if (data.type === "note") {
477	        await handleNoteDragEnd(event);
478	      }
479	    },
480	    [handleFolderDragEnd, handleNoteDragEnd]
481	  );
482	
483	  const handleDragCancel = useCallback(() => {
484	    setActiveId(null);
485	    setEdgeSnap(null);
486	    document.body.style.setProperty("cursor", "");
487	    dragStartPoint.current = null;
488	    activeDrag.current = null;
489	    if (expandTimeoutRef.current) {
490	      window.clearTimeout(expandTimeoutRef.current);
491	      expandTimeoutRef.current = null;
492	    }
493	    expandTargetRef.current = null;
494	  }, []);
495	
496	  return {
497	    activeId,
498	    edgeSnap,
499	    handleDragStart,
500	    handleDragMove,
501	    handleDragOver,
502	    handleDragEnd,
503	    handleDragCancel,
504	  };
505	}
