38	/**
39	 * The embedded-sidebar counterpart to {@link TreeNode}: renders the folder tree
40	 * (and, optionally, notes as children) using the shadcn Sidebar primitives and
41	 * without drag-and-drop. Used by FoldersPanel's `embedded` mode.
42	 */
43	export function SidebarFileTreeNode({
44	  node,
45	  selectedIds,
46	  selectedNoteIds,
47	  showNotesAsChildren,
48	  expanded,
49	  onSelect,
50	  onToggle,
51	  onNoteSelect,
52	  onNoteContextMenu,
53	  notePreviews,
54	  renamingFolder = null,
55	  renameValue = "",
56	  setRenameValue = () => {
57	    return;
58	  },
59	  submitRenameFolder = () => {
60	    return;
61	  },
62	  cancelRenameFolder = () => {
63	    return;
64	  },
65	  onContextMenu,
66	}: SidebarFileTreeNodeProps) {
67	  const notes = showNotesAsChildren ? node.notes || [] : [];
68	  const hasNestedItems = node.children.length > 0 || notes.length > 0;
69	  const isExpanded = !hasNestedItems || expanded.has(node.id);
70	  const isRenaming = renamingFolder === node.id;
71	
72	  return (
73	    <SidebarMenuItem>
74	      <Collapsible open={isExpanded} className="group/collapsible">
75	        <SidebarMenuButton
76	          isActive={selectedIds.has(node.id)}
77	          className="sidebar-filetree-button"
78	          asChild
79	        >
80	          <div
81	            className="sidebar-filetree-button-inner"
82	            onClick={(event) => {
83	              onSelect(event, node.id);
84	            }}
85	            onContextMenu={(event) => {
86	              onContextMenu(event, node.id);
87	            }}
88	          >
89	            {hasNestedItems ? (
90	              <button
91	                type="button"
92	                className="sidebar-filetree-toggle"
93	                onClick={(event) => {
94	                  event.stopPropagation();
95	                  onToggle(event, node.id);
96	                }}
97	                aria-label={isExpanded ? "Collapse folder" : "Expand folder"}
98	              >
99	                <ChevronRight
100	                  className={`sidebar-filetree-chevron${isExpanded ? " is-open" : ""}`}
101	                />
102	              </button>
103	            ) : (
104	              <span className="sidebar-filetree-toggle-spacer" aria-hidden />
105	            )}
106	            <Folder />
107	            {isRenaming ? (
108	              <input
109	                className="rename-input sidebar-filetree-rename-input"
110	                value={renameValue}
111	                autoFocus
112	                onChange={(event) => setRenameValue(event.target.value)}
113	                onBlur={submitRenameFolder}
114	                onKeyDown={(event) => {
115	                  event.stopPropagation();
116	                  if (event.key === "Enter") {
117	                    submitRenameFolder();
118	                  }
119	                  if (event.key === "Escape") {
120	                    cancelRenameFolder();
121	                  }
122	                }}
123	                onMouseDown={(event) => event.stopPropagation()}
124	                onClick={(event) => event.stopPropagation()}
125	              />
126	            ) : (
127	              <span>{node.name}</span>
128	            )}
129	          </div>
130	        </SidebarMenuButton>
131	        {!isRenaming && node.noteCount ? <SidebarMenuBadge>{node.noteCount}</SidebarMenuBadge> : null}
132	        {hasNestedItems ? (
